// Было
static int factorial(int num)
{
    int result;
    if (num == 1) { result = 1; }
    else { result = (factorial(num - 1) * num); }
    return result;
}

// Стало
static int factorial(int num)
{
    return (num == 1) ? 1 : (factorial(num - 1) * num);
}

